migrations.sql:
-- Additive local-development storage. Apply explicitly to the local D1 database.
CREATE TABLE IF NOT EXISTS rer_mail_development_outbox (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  created_at INTEGER NOT NULL,
  message TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS rer_mail_development_outbox_order
  ON rer_mail_development_outbox(created_at DESC, sequence DESC);

CREATE TABLE rer_portability_state (
  id INTEGER PRIMARY KEY CHECK(id=1), source_identity TEXT NOT NULL, epoch INTEGER NOT NULL DEFAULT 0,
  import_job TEXT, applying INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE rer_portability_jobs (
  id TEXT PRIMARY KEY, kind TEXT NOT NULL, actor TEXT NOT NULL, phase TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0, metadata TEXT NOT NULL
);
CREATE TABLE rer_portability_parts (
  job TEXT NOT NULL REFERENCES rer_portability_jobs(id) ON DELETE CASCADE,
  idx INTEGER NOT NULL, sha256 TEXT NOT NULL, PRIMARY KEY(job,idx)
);
CREATE TABLE rer_portability_segments (
  job TEXT NOT NULL REFERENCES rer_portability_jobs(id) ON DELETE CASCADE,
  part INTEGER NOT NULL, segment INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY(job,part,segment)
);
CREATE TABLE rer_portability_owned (
  job TEXT NOT NULL REFERENCES rer_portability_jobs(id) ON DELETE CASCADE,
  bucket TEXT NOT NULL, key TEXT NOT NULL, PRIMARY KEY(job,bucket,key)
);
CREATE TABLE rer_portability_journal (
  source TEXT NOT NULL, tombstone TEXT NOT NULL, PRIMARY KEY(source,tombstone)
);
CREATE TABLE rer_portability_epochs (source TEXT PRIMARY KEY, epoch INTEGER NOT NULL);
CREATE TABLE rer_portability_guard (value INTEGER NOT NULL CHECK(value=1));

-- Local dev identity for an existing store. Apply as a NEW numbered migration
-- under the seed's next unused number; never rewrite an applied migration.
-- SQLite cannot change a CHECK in place, so oa_sessions is rebuilt with 'dev'
-- admitted, keeping every row, column, index and constraint. No table refers
-- to oa_sessions. The file is also safe on a store created from the current
-- schema/operator-auth.sql, so a fresh store may apply both.
CREATE TABLE oa_sessions_dev_rebuild (
 id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE,
 operator_id TEXT NOT NULL REFERENCES oa_operators(id), operator_version INTEGER NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('native','review','oidc','password','dev')),
 source_token_id TEXT UNIQUE REFERENCES oa_tokens(id),
 created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER
);
INSERT INTO oa_sessions_dev_rebuild(id,token_hash,operator_id,operator_version,kind,source_token_id,created_at,expires_at,revoked_at)
 SELECT id,token_hash,operator_id,operator_version,kind,source_token_id,created_at,expires_at,revoked_at FROM oa_sessions;
DROP TABLE oa_sessions;
ALTER TABLE oa_sessions_dev_rebuild RENAME TO oa_sessions;
CREATE INDEX oa_sessions_operator ON oa_sessions(operator_id);
CREATE TABLE IF NOT EXISTS oa_dev_credentials (
 credential TEXT NOT NULL, id TEXT NOT NULL, created_at INTEGER NOT NULL,
 PRIMARY KEY(credential, id)
);

-- Auth-specific security state; directory identity remains Base's real oa_operators.
CREATE TABLE auth_emails (person_id TEXT PRIMARY KEY REFERENCES oa_operators(id), verified_at INTEGER NOT NULL);
CREATE TABLE auth_sessions (id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, person_id TEXT NOT NULL REFERENCES oa_operators(id), person_version INTEGER NOT NULL, amr TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER);
CREATE INDEX auth_sessions_person ON auth_sessions(person_id);
CREATE TABLE auth_challenges (id TEXT PRIMARY KEY, purpose TEXT NOT NULL, person_id TEXT, binding_hash TEXT NOT NULL, payload TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE auth_limits (bucket TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE auth_passkeys (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES oa_operators(id), public_key TEXT NOT NULL, counter INTEGER NOT NULL, transports TEXT NOT NULL, created_at INTEGER NOT NULL, last_used_at INTEGER);
CREATE INDEX auth_passkeys_person ON auth_passkeys(person_id);
CREATE TABLE auth_recoveries (id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES oa_operators(id), session_id TEXT NOT NULL, created_at INTEGER NOT NULL, ready_at INTEGER NOT NULL, approved_by TEXT REFERENCES oa_operators(id), cancelled_at INTEGER, completed_at INTEGER, completion_marker TEXT);
CREATE UNIQUE INDEX auth_recovery_pending ON auth_recoveries(person_id) WHERE cancelled_at IS NULL AND completed_at IS NULL;
CREATE TABLE auth_notices (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES auth_sessions(id), recovery_id TEXT REFERENCES auth_recoveries(id), message TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE auth_recovery_tokens (token_hash TEXT PRIMARY KEY, created_at INTEGER NOT NULL, consumed_at INTEGER, consumption_marker TEXT);
CREATE TABLE auth_domains (domain TEXT PRIMARY KEY, created_by TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE auth_activity (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_id TEXT, event TEXT NOT NULL, subject_id TEXT, created_at INTEGER NOT NULL);
CREATE TABLE auth_clients (id TEXT PRIMARY KEY, name TEXT NOT NULL, origin TEXT NOT NULL, sector_id TEXT NOT NULL UNIQUE, redirect_uris TEXT NOT NULL, jwks TEXT NOT NULL, owner_person_id TEXT REFERENCES oa_operators(id), owner_claimed_at INTEGER, source TEXT NOT NULL, created_at INTEGER NOT NULL, disabled_at INTEGER);
CREATE TABLE auth_grants (client_id TEXT NOT NULL REFERENCES auth_clients(id), person_id TEXT NOT NULL REFERENCES oa_operators(id), created_at INTEGER NOT NULL, PRIMARY KEY(client_id,person_id));
CREATE TABLE auth_codes (code_hash TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES auth_clients(id), person_id TEXT NOT NULL REFERENCES oa_operators(id), session_id TEXT NOT NULL REFERENCES auth_sessions(id), redirect_uri TEXT NOT NULL, challenge TEXT NOT NULL, nonce TEXT NOT NULL, scopes TEXT NOT NULL, expires_at INTEGER NOT NULL, consumed_at INTEGER);
CREATE TABLE auth_assertions (client_id TEXT NOT NULL, jti TEXT NOT NULL, expires_at INTEGER NOT NULL, PRIMARY KEY(client_id,jti));
CREATE TABLE auth_signing_keys (kid TEXT PRIMARY KEY, public_jwk TEXT NOT NULL, encrypted_private TEXT NOT NULL, published_at INTEGER NOT NULL, use_after INTEGER NOT NULL, retire_at INTEGER);
CREATE TABLE auth_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE auth_subjects (sector_id TEXT NOT NULL, person_id TEXT NOT NULL REFERENCES oa_operators(id), subject TEXT NOT NULL UNIQUE, PRIMARY KEY(sector_id,person_id));

-- Provenance is written only after the upstream adapter verifies an OIDC response.
CREATE TABLE auth_upstream_proofs (
 id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES oa_operators(id),
 provider_id TEXT NOT NULL, issuer TEXT NOT NULL, subject TEXT NOT NULL,
 configuration_hash TEXT NOT NULL, verified_at INTEGER NOT NULL, expires_at INTEGER NOT NULL
);
ALTER TABLE auth_sessions ADD COLUMN upstream_proof_id TEXT;

-- Only a completed Auth browser-bound email challenge supplies this timestamp.
-- Existing sessions keep sign-in access but have no local step-up provenance.
ALTER TABLE auth_sessions ADD COLUMN local_email_verified_at INTEGER;

-- Move-in staging is separate from people: a staged row can sign in to nothing,
-- receives no mail and is listed only on the move-in review. Admission creates an
-- ordinary invitation; the row then names the person it created.
CREATE TABLE auth_import_batches (
 id TEXT PRIMARY KEY, source_system TEXT NOT NULL, format TEXT NOT NULL, file_name TEXT NOT NULL,
 file_hash TEXT NOT NULL UNIQUE, export_date TEXT NOT NULL, row_count INTEGER NOT NULL,
 created_by TEXT NOT NULL REFERENCES oa_operators(id), created_at INTEGER NOT NULL,
 undone_at INTEGER, undo_report TEXT
);
CREATE TABLE auth_import_rows (
 batch_id TEXT NOT NULL REFERENCES auth_import_batches(id), idx INTEGER NOT NULL,
 source_id TEXT, email TEXT, display_name TEXT, disabled INTEGER, groups TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('staged','admitted','undone')), reasons TEXT NOT NULL,
 person_id TEXT REFERENCES oa_operators(id), admitted_at INTEGER, invited_at INTEGER,
 PRIMARY KEY(batch_id,idx)
);
CREATE INDEX auth_import_rows_person ON auth_import_rows(person_id);
-- An old provider subject kept against the person it was admitted as. It is data
-- for app owners to rebind deliberately, never a credential or an Auth subject.
CREATE TABLE auth_former_subjects (
 source_system TEXT NOT NULL, subject TEXT NOT NULL, person_id TEXT NOT NULL REFERENCES oa_operators(id),
 batch_id TEXT NOT NULL REFERENCES auth_import_batches(id), created_at INTEGER NOT NULL,
 PRIMARY KEY(source_system,subject)
);
CREATE INDEX auth_former_subjects_person ON auth_former_subjects(person_id);
-- Names behind an audit entry, such as who an undo removed and who it kept.
CREATE TABLE auth_activity_details (activity_id INTEGER PRIMARY KEY REFERENCES auth_activity(id), detail TEXT NOT NULL);

-- Additive provider controls. An absent setting means off, including upgrades.
CREATE TABLE IF NOT EXISTS oa_auth_settings (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), idp_sign_in INTEGER NOT NULL CHECK(idp_sign_in IN (0,1)), generation INTEGER NOT NULL DEFAULT 0, first_setup INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS oa_auth_audit (
 id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, value TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS oa_provider_sessions (
 session_id TEXT PRIMARY KEY, issuer TEXT NOT NULL, subject TEXT NOT NULL, sid TEXT, generation INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS oa_provider_session_identity ON oa_provider_sessions(issuer,subject,sid);
CREATE TABLE IF NOT EXISTS oa_logout_events (
 issuer TEXT NOT NULL, jti TEXT NOT NULL, consumed_at INTEGER NOT NULL CHECK(consumed_at>=0), PRIMARY KEY(issuer,jti)
);

CREATE TRIGGER IF NOT EXISTS oa_first_setup_provider_setting AFTER INSERT ON oa_bootstrap BEGIN
 INSERT INTO oa_auth_settings(singleton,idp_sign_in,generation,first_setup) VALUES(1,0,0,1) ON CONFLICT DO NOTHING;
END;

CREATE TABLE IF NOT EXISTS oa_credentials (
 id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, operator_id TEXT NOT NULL REFERENCES oa_operators(id),
 operator_version INTEGER, kind TEXT NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER
);

-- Session provenance for OIDC pins. Apply as a new migration on existing stores.
-- External admission has no OIDC pin and does not require OIDC protocol tables.
CREATE TABLE IF NOT EXISTS oa_provider_session_pins (
 session_id TEXT PRIMARY KEY, provider_id TEXT NOT NULL, issuer TEXT NOT NULL,
 client_id TEXT NOT NULL, linked_at INTEGER NOT NULL
);

-- Session provenance for OIDC pins. Apply as a new migration on existing stores.
-- External admission has no OIDC pin and does not require OIDC protocol tables.
CREATE TABLE IF NOT EXISTS oa_provider_session_pins (
 session_id TEXT PRIMARY KEY, provider_id TEXT NOT NULL, issuer TEXT NOT NULL,
 client_id TEXT NOT NULL, linked_at INTEGER NOT NULL
);

-- Ephemeral app-local setup attempts are never exported. A native claim binds
-- only attempts opened before that claim to its exact owner/session authority,
-- in its own bootstrap transaction.
CREATE TABLE IF NOT EXISTS oa_setup_links (
 interface TEXT PRIMARY KEY, attempt_id TEXT NOT NULL, expires_at INTEGER NOT NULL,
 owner_id TEXT, owner_version INTEGER, session_id TEXT,
 completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0,1))
);
CREATE TRIGGER IF NOT EXISTS oa_native_claim_closes_provider_setup AFTER INSERT ON oa_sessions
WHEN NEW.kind='native' AND NOT EXISTS(SELECT 1 FROM oa_sessions WHERE operator_id=NEW.operator_id AND id!=NEW.id) AND EXISTS(SELECT 1 FROM oa_bootstrap WHERE claim_id=NEW.operator_id AND claimed_at=NEW.created_at)
BEGIN
 UPDATE oa_auth_settings SET first_setup=0 WHERE singleton=1 AND NOT EXISTS(
  SELECT 1 FROM oa_setup_links WHERE interface='oidc-provider@1' AND completed=0 AND owner_id IS NULL AND expires_at>NEW.created_at
 );
 UPDATE oa_setup_links SET owner_id=NEW.operator_id,owner_version=NEW.operator_version,session_id=NEW.id
 WHERE owner_id IS NULL AND completed=0 AND expires_at>NEW.created_at;
END;

CREATE TABLE IF NOT EXISTS rer_dependency_installation (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), sector_id TEXT NOT NULL UNIQUE
);
CREATE TABLE IF NOT EXISTS rer_dependency_link (
 interface TEXT PRIMARY KEY, issuer TEXT NOT NULL, client_id TEXT NOT NULL, metadata TEXT NOT NULL,
 needs_relink INTEGER NOT NULL DEFAULT 0, linked_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS rer_dependency_pending (
 interface TEXT PRIMARY KEY, issuer TEXT NOT NULL, approved_by TEXT NOT NULL, expires_at INTEGER NOT NULL, approved_session TEXT NOT NULL, approved_version INTEGER NOT NULL, callbacks TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS rer_dependency_codes (
 digest TEXT PRIMARY KEY, created_at INTEGER NOT NULL CHECK(created_at>=0)
);

CREATE TABLE IF NOT EXISTS rer_dependency_keys (interface TEXT PRIMARY KEY, private_key TEXT NOT NULL);

-- Existing pending approvals predate attempt fencing and must be renewed.
ALTER TABLE rer_dependency_pending ADD COLUMN attempt_id TEXT;
DELETE FROM rer_dependency_pending;

-- Apps linked through the oidc-provider@1 pull handshake. A client keeps its
-- id and sector for life; a re-link replaces only its key, callbacks and source.
ALTER TABLE auth_clients ADD COLUMN interface TEXT NOT NULL DEFAULT 'oidc-provider@1';
ALTER TABLE auth_clients ADD COLUMN logout_uri TEXT;
ALTER TABLE auth_clients ADD COLUMN post_logout_redirect_uris TEXT NOT NULL DEFAULT '[]';
ALTER TABLE auth_clients ADD COLUMN linked_at INTEGER;
ALTER TABLE auth_clients ADD COLUMN approved_by TEXT;

-- Every origin Auth has ever pulled, so approval can flag a first-seen origin.
CREATE TABLE auth_origins_seen (origin TEXT PRIMARY KEY, first_seen_at INTEGER NOT NULL);

-- Interface versions live clients report. A lower version than one already
-- reported waits for an owner's approval (approved_at NULL until then).
CREATE TABLE auth_client_versions (
 client_id TEXT NOT NULL REFERENCES auth_clients(id), version TEXT NOT NULL,
 reported_at INTEGER NOT NULL, approved_by TEXT, approved_at INTEGER,
 PRIMARY KEY(client_id, version)
);

-- An administrator's pending approval of an app origin, with what was pulled.
CREATE TABLE auth_link_requests (
 id TEXT PRIMARY KEY, origin TEXT NOT NULL, interface TEXT NOT NULL, app TEXT NOT NULL,
 client_id TEXT, key_changed INTEGER NOT NULL, first_seen INTEGER NOT NULL, punycode INTEGER NOT NULL,
 requested_by TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL,
 decided_by TEXT, decided_at INTEGER, outcome TEXT
);
CREATE INDEX auth_link_requests_open ON auth_link_requests(decided_at, expires_at);

-- One-use link tokens for `rer setup --non-interactive`: one exact origin and
-- callback set, at most an hour. Only the digest is kept.
CREATE TABLE auth_link_tokens (
 token_hash TEXT PRIMARY KEY, origin TEXT NOT NULL, interface TEXT NOT NULL, callbacks TEXT NOT NULL,
 created_by TEXT NOT NULL, issued_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, consumed_at INTEGER
);

-- Short one-use codes posted to an app's fixed link callback and redeemed by
-- a request the app signs with its link key.
CREATE TABLE auth_link_codes (
 code_hash TEXT PRIMARY KEY, origin TEXT NOT NULL, interface TEXT NOT NULL, callback TEXT NOT NULL,
 sector_id TEXT NOT NULL, link TEXT NOT NULL, expires_at INTEGER NOT NULL, consumed_at INTEGER
);

-- Which apps received tokens from which Auth session, for session-scoped logout.
CREATE TABLE auth_session_clients (
 session_id TEXT NOT NULL REFERENCES auth_sessions(id), client_id TEXT NOT NULL REFERENCES auth_clients(id),
 PRIMARY KEY(session_id, client_id)
);

-- Back-channel logout and fence deliveries, retried for up to 24 hours.
CREATE TABLE auth_logout_deliveries (
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES auth_clients(id), person_id TEXT NOT NULL,
 event TEXT NOT NULL, sid TEXT, jti TEXT NOT NULL UNIQUE, attempts INTEGER NOT NULL DEFAULT 0,
 next_attempt_at INTEGER NOT NULL, created_at INTEGER NOT NULL, finished_at INTEGER, outcome TEXT
);
CREATE INDEX auth_logout_due ON auth_logout_deliveries(finished_at, next_attempt_at);

-- Agents may now also propose linking or removing an app. SQLite cannot widen a
-- CHECK in place, so the proposals table is rebuilt with the same columns and rows.
CREATE TABLE auth_agent_proposals_next (
 id TEXT PRIMARY KEY, key_id TEXT NOT NULL REFERENCES auth_agent_keys(id),
 kind TEXT NOT NULL CHECK(kind IN ('suspend_person','restore_person','invite_person','remove_invitation','add_domain_rule','remove_domain_rule','approve_app_link','remove_app_link')),
 target TEXT NOT NULL, params TEXT NOT NULL, reason TEXT NOT NULL,
 effect TEXT NOT NULL, target_state TEXT NOT NULL, state_digest TEXT NOT NULL,
 created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL,
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','done','rejected','failed')),
 decided_by TEXT REFERENCES oa_operators(id), decided_at INTEGER, outcome TEXT, execution_id TEXT UNIQUE
);
INSERT INTO auth_agent_proposals_next SELECT id,key_id,kind,target,params,reason,effect,target_state,state_digest,created_at,expires_at,status,decided_by,decided_at,outcome,execution_id FROM auth_agent_proposals;
DROP TABLE auth_agent_proposals;
ALTER TABLE auth_agent_proposals_next RENAME TO auth_agent_proposals;
CREATE INDEX auth_agent_proposals_key ON auth_agent_proposals(key_id);
CREATE INDEX auth_agent_proposals_pending ON auth_agent_proposals(status,created_at);

-- Signed grant maps written at export: every (sector, person, pairwise subject)
-- and former subject, signed with Auth's key, so a later provider can rebind.
CREATE TABLE auth_grant_maps (id TEXT PRIMARY KEY, issuer TEXT NOT NULL, created_at INTEGER NOT NULL, map TEXT NOT NULL);

-- RER Managed: the per-account keys whose signed link approvals this install
-- accepts. A provisioned key comes from the RER_LINK_APPROVAL_KEYS binding RER
-- set when it installed Auth; an owner-added key was registered on Sign-in
-- methods. Withdrawal is recorded here for both and is never undone.
CREATE TABLE auth_rer_trust (
 kid TEXT PRIMARY KEY, public_jwk TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN ('provisioned','owner')),
 added_by TEXT, added_at INTEGER NOT NULL, withdrawn_by TEXT, withdrawn_at INTEGER
);
-- Each approval's jti is accepted once.
CREATE TABLE auth_rer_approvals (jti TEXT PRIMARY KEY, kid TEXT NOT NULL, expires_at INTEGER NOT NULL);

-- Withdrawn RER keys get their own table, which export carries, so a restored
-- install keeps them withdrawn: withdrawal ends a key for good. auth_rer_trust
-- keeps only the keys an owner added; a provisioned key's row existed only to
-- record its withdrawal.
CREATE TABLE auth_rer_withdrawals (
 kid TEXT PRIMARY KEY, source TEXT NOT NULL CHECK(source IN ('provisioned','owner')),
 withdrawn_by TEXT, withdrawn_at INTEGER NOT NULL
);
INSERT INTO auth_rer_withdrawals(kid,source,withdrawn_by,withdrawn_at) SELECT kid,source,withdrawn_by,withdrawn_at FROM auth_rer_trust WHERE withdrawn_at IS NOT NULL;
DELETE FROM auth_rer_trust WHERE source='provisioned';
ALTER TABLE auth_rer_trust DROP COLUMN withdrawn_by;
ALTER TABLE auth_rer_trust DROP COLUMN withdrawn_at;

-- Workforce apps: groups, company (SAML) apps and who is assigned to them.
CREATE TABLE auth_groups (
 id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE,
 created_by TEXT NOT NULL, created_at INTEGER NOT NULL
);
CREATE TABLE auth_group_members (
 group_id TEXT NOT NULL REFERENCES auth_groups(id), person_id TEXT NOT NULL REFERENCES oa_operators(id),
 added_by TEXT NOT NULL, added_at INTEGER NOT NULL, PRIMARY KEY(group_id, person_id)
);
CREATE INDEX auth_group_members_person ON auth_group_members(person_id);

-- One company app; its SAML settings live on the row, its catalog recipe (if
-- any) is named, and version counts every configuration change.
CREATE TABLE auth_apps (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, recipe TEXT, launch_url TEXT,
 entity_id TEXT NOT NULL UNIQUE, acs TEXT NOT NULL, slo TEXT,
 sp_certificates TEXT NOT NULL DEFAULT '[]', encryption_certificate TEXT,
 name_id_format TEXT NOT NULL, name_id_source TEXT CHECK(name_id_source IN ('person_id','email')), sign TEXT NOT NULL CHECK(sign IN ('response','assertion','both')),
 digest TEXT NOT NULL CHECK(digest IN ('sha256','sha512','sha1')), sha1_exception INTEGER NOT NULL DEFAULT 0,
 encryption TEXT CHECK(encryption IN ('aes256-gcm','aes128-cbc')), want_requests_signed INTEGER NOT NULL DEFAULT 0,
 idp_initiated INTEGER NOT NULL DEFAULT 0, relay_state TEXT, attributes TEXT NOT NULL DEFAULT '[]',
 version INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
 disabled_at INTEGER
);
CREATE TABLE auth_app_assignments (
 app_id TEXT NOT NULL REFERENCES auth_apps(id), principal_type TEXT NOT NULL CHECK(principal_type IN ('person','group')),
 principal_id TEXT NOT NULL, role TEXT, created_by TEXT NOT NULL, created_at INTEGER NOT NULL,
 PRIMARY KEY(app_id, principal_type, principal_id)
);

-- SAML signing certificates: next (published, not yet signing), active,
-- previous (still published) and retired.
CREATE TABLE auth_saml_keys (
 kid TEXT PRIMARY KEY, certificate TEXT NOT NULL, encrypted_private TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('next','active','previous','retired')),
 created_at INTEGER NOT NULL, activated_at INTEGER, retired_at INTEGER
);
CREATE UNIQUE INDEX auth_saml_keys_one_active ON auth_saml_keys(state) WHERE state='active';
-- Request IDs already answered, so a captured request cannot be replayed.
CREATE TABLE auth_saml_requests (app_id TEXT NOT NULL, request_id TEXT NOT NULL, expires_at INTEGER NOT NULL, PRIMARY KEY(app_id, request_id));
-- Which apps an Auth session signed in through SAML, for single logout.
CREATE TABLE auth_saml_sessions (
 session_id TEXT NOT NULL, app_id TEXT NOT NULL, name_id TEXT NOT NULL, name_id_format TEXT NOT NULL,
 session_index TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, ended_at INTEGER,
 PRIMARY KEY(session_id, app_id)
);
-- A single logout in progress: apps still to visit, the one awaiting a
-- response (matched by its request ID), and the app (if any) that asked.
CREATE TABLE auth_saml_logouts (
 id TEXT PRIMARY KEY, session_id TEXT NOT NULL, pending TEXT NOT NULL,
 awaiting_app TEXT, awaiting_request TEXT, origin_app TEXT, origin_request TEXT, origin_relay TEXT,
 expires_at INTEGER NOT NULL
);

-- Outbound provisioning (SCIM 2.0). The bearer credential is sealed under
-- AUTH_ENCRYPTION_KEY and never returned.
CREATE TABLE auth_scim_connectors (
 app_id TEXT PRIMARY KEY REFERENCES auth_apps(id), base_url TEXT NOT NULL, sealed_token TEXT NOT NULL,
 deprovision TEXT NOT NULL CHECK(deprovision IN ('deactivate','delete')), push_groups INTEGER NOT NULL DEFAULT 0,
 created_by TEXT NOT NULL, created_at INTEGER NOT NULL, rotated_at INTEGER, last_success_at INTEGER, last_error TEXT,
 last_reconciled_at INTEGER
);
-- The remote account Auth manages for a person (or the remote group for a group).
CREATE TABLE auth_scim_accounts (
 app_id TEXT NOT NULL, subject_type TEXT NOT NULL CHECK(subject_type IN ('person','group')), subject_id TEXT NOT NULL,
 remote_id TEXT NOT NULL, state TEXT NOT NULL, updated_at INTEGER NOT NULL,
 PRIMARY KEY(app_id, subject_type, subject_id)
);
-- One open obligation per app and subject: what Auth still has to make true
-- remotely, with event, dispatch and remote-verified times.
CREATE TABLE auth_provisioning (
 id TEXT PRIMARY KEY, app_id TEXT NOT NULL, subject_type TEXT NOT NULL, subject_id TEXT NOT NULL,
 reason TEXT NOT NULL, event_at INTEGER NOT NULL, dispatched_at INTEGER, verified_at INTEGER,
 operation TEXT, state TEXT NOT NULL CHECK(state IN ('pending','verified','failed','blocked','superseded')),
 attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at INTEGER NOT NULL, last_status INTEGER, last_error TEXT,
 claimed_until INTEGER
);
CREATE UNIQUE INDEX auth_provisioning_open ON auth_provisioning(app_id, subject_type, subject_id) WHERE state IN ('pending','failed','blocked');
CREATE INDEX auth_provisioning_due ON auth_provisioning(state, next_attempt_at);

-- Company apps that sign in with OpenID Connect (the general SaaS profile,
-- kept apart from RER clients). For these apps the SAML columns of auth_apps
-- hold inert defaults and entity_id holds 'oidc:' and the client ID.
ALTER TABLE auth_apps ADD COLUMN protocol TEXT NOT NULL DEFAULT 'saml' CHECK(protocol IN ('saml','oidc'));
CREATE TABLE auth_oidc_clients (
 app_id TEXT PRIMARY KEY REFERENCES auth_apps(id), client_id TEXT NOT NULL UNIQUE,
 auth_method TEXT NOT NULL CHECK(auth_method IN ('client_secret_basic','client_secret_post','private_key_jwt','none')),
 jwks TEXT, redirect_uris TEXT NOT NULL, post_logout_redirect_uris TEXT NOT NULL DEFAULT '[]',
 require_pkce INTEGER NOT NULL, subject_type TEXT NOT NULL CHECK(subject_type IN ('public','pairwise')),
 legacy_flows INTEGER NOT NULL DEFAULT 0, frontchannel_logout_uri TEXT, backchannel_logout_uri TEXT,
 id_token_alg TEXT NOT NULL CHECK(id_token_alg IN ('ES256','RS256'))
);
-- Client secrets: only a digest. A rotated-out secret keeps working until expires_at.
CREATE TABLE auth_oidc_secrets (
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL, secret_hash TEXT NOT NULL UNIQUE,
 created_at INTEGER NOT NULL, expires_at INTEGER
);
CREATE INDEX auth_oidc_secrets_client ON auth_oidc_secrets(client_id);
CREATE TABLE auth_oidc_codes (
 code_hash TEXT PRIMARY KEY, client_id TEXT NOT NULL, person_id TEXT NOT NULL, session_id TEXT NOT NULL,
 redirect_uri TEXT NOT NULL, challenge TEXT, nonce TEXT, scopes TEXT NOT NULL, expires_at INTEGER NOT NULL
);
-- Which OIDC apps an Auth session signed in to, for front- and back-channel logout.
CREATE TABLE auth_oidc_sessions (session_id TEXT NOT NULL, client_id TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(session_id, client_id));
CREATE TABLE auth_oidc_logouts (
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL, person_id TEXT NOT NULL, sid TEXT NOT NULL, jti TEXT NOT NULL UNIQUE,
 attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at INTEGER NOT NULL, created_at INTEGER NOT NULL, finished_at INTEGER, outcome TEXT
);

-- Lifecycle events in commit order (seq is the cursor), and their delivery to
-- subscribers. Subscriber signing secrets are sealed; read keys are digests.
CREATE TABLE auth_events (
 seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, type TEXT NOT NULL, version INTEGER NOT NULL,
 subject TEXT NOT NULL, data TEXT NOT NULL, occurred_at INTEGER NOT NULL
);
CREATE TABLE auth_event_subscriptions (
 id TEXT PRIMARY KEY, url TEXT NOT NULL, types TEXT NOT NULL, sealed_secrets TEXT NOT NULL, read_key_hash TEXT NOT NULL UNIQUE,
 created_by TEXT NOT NULL, created_at INTEGER NOT NULL, disabled_at INTEGER
);
CREATE TABLE auth_event_deliveries (
 subscription_id TEXT NOT NULL, seq INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at INTEGER NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('pending','delivered','failed','abandoned')), last_status INTEGER, delivered_at INTEGER, claimed_until INTEGER,
 PRIMARY KEY(subscription_id, seq)
);
CREATE INDEX auth_event_deliveries_due ON auth_event_deliveries(state, next_attempt_at);

-- The workforce directory: typed attributes, values kept per source so
-- precedence and manual overrides stay visible, source identifiers, and
-- attribute-driven group membership with explicit exclusions and owners.
CREATE TABLE auth_attribute_defs (
 name TEXT PRIMARY KEY, label TEXT NOT NULL,
 type TEXT NOT NULL CHECK(type IN ('text','number','boolean','date','choice')), choices TEXT,
 visibility TEXT NOT NULL CHECK(visibility IN ('employee','admin')), employee_editable INTEGER NOT NULL DEFAULT 0,
 created_by TEXT NOT NULL, created_at INTEGER NOT NULL
);
-- One value per person, field and source. The effective value is the highest
-- ranked source's: manual (an administrator's override), hr, directory, self.
CREATE TABLE auth_person_fields (
 person_id TEXT NOT NULL REFERENCES oa_operators(id), field TEXT NOT NULL,
 source TEXT NOT NULL CHECK(source IN ('manual','hr','directory','self')), value TEXT NOT NULL,
 set_by TEXT, set_at INTEGER NOT NULL, PRIMARY KEY(person_id, field, source)
);
CREATE INDEX auth_person_fields_field ON auth_person_fields(field, value);
-- A source's identifier for a person, bound once and never changed or reused.
CREATE TABLE auth_person_sources (
 source TEXT NOT NULL CHECK(source IN ('hr','directory')), source_id TEXT NOT NULL,
 person_id TEXT NOT NULL REFERENCES oa_operators(id), bound_by TEXT NOT NULL, bound_at INTEGER NOT NULL,
 PRIMARY KEY(source, source_id), UNIQUE(source, person_id)
);
-- Directory facts beside Base's person row: when a person was terminated.
CREATE TABLE auth_people (person_id TEXT PRIMARY KEY REFERENCES oa_operators(id), terminated_at INTEGER);
CREATE TRIGGER auth_people_rehired AFTER UPDATE OF status ON oa_operators
 WHEN OLD.status='inactive' AND NEW.status!='inactive'
 BEGIN UPDATE auth_people SET terminated_at=NULL WHERE person_id=NEW.id; END;

